import { cachedLogs } from './event-store.js';
import { contractInterface, decodeLog, compareLogs, ChainDataError } from './client.js';

// History is indexed by accepted daily requests, never by elapsed wall resets. Retries reuse
// the current day; only the first request after a completed daily opens the next one.
export function indexLogicalDays(events, { deployBlock, currentDay, head }) {
  const starts = new Map([[1, {blockNumber:Number(deployBlock)}]]);
  let day = 1, complete = true;
  for (const event of [...events].sort(compareLogs)) {
    if (event.name === 'DailySessionCompleted') {
      if (Number(event.args.day) === day) complete = true;
    } else if (event.name === 'Advance' && Number(event.args.stage) === 1 && complete && day < currentDay) {
      starts.set(++day, event);
      complete = false;
    } else if (event.name === 'DailyRngApplied' && Number(event.args.day) !== day) {
      throw new ChainDataError('Daily history is incomplete; retry the chain read.');
    }
  }
  if (day !== currentDay) throw new ChainDataError('Daily request history does not match the current game day.');
  return new Map([...starts].map(([n, start]) => {
    const end = starts.get(n + 1);
    return [n, {fromBlock:Number(start.blockNumber), toBlock:end ? Number(end.blockNumber) : Number(head),
      fromEvent:n === 1 ? null : start, toEvent:end ?? null}];
  }));
}

export async function logicalDayRanges(snapshot) {
  if (!snapshot.logicalDays) {
    const pending = (async () => {
      const iface = await contractInterface('GAME');
      const currentDay = Number(await snapshot.field('GAME', 'dailyIdx'));
      const logs = currentDay <= 1 ? [] : await cachedLogs(snapshot, {
        address: snapshot.client.address('GAME'),
        topics: [['Advance', 'DailyRngApplied', 'DailySessionCompleted'].map(name => iface.getEvent(name).topicHash)],
      }, { fromBlock: Number(snapshot.client.chain.deployBlock) });
      return indexLogicalDays(logs.map(log => ({ ...log, ...decodeLog(iface, log) })), {
        currentDay, deployBlock: snapshot.client.chain.deployBlock, head: snapshot.block.number,
      });
    })();
    snapshot.logicalDays = pending;
    pending.catch(() => { if (snapshot.logicalDays === pending) snapshot.logicalDays = null; });
  }
  return snapshot.logicalDays;
}
